daily-overtime.to:
let regular = 0, overtime = 0;
for (let d = week * 7; d < week * 7 + 7; d++) {
  const m = this.minutesWorked(id, d * 1440, (d + 1) * 1440);
  regular += Math.min(m, 480);
  overtime += Math.max(0, m - 480);
}

round-per-shift.from:
const minutes = this.minutesWorked(id, week * WEEK, (week + 1) * WEEK);
const regular = Math.min(minutes, OVERTIME_AFTER), overtime = minutes - regular;
return Math.round((regular * w.rate + overtime * w.rate * 1.5) / 60); // rounded once, for the whole week

round-per-shift.to:
let minutes = 0, cents = 0;
for (const s of [...w.shifts].sort((a, b) => a.start - b.start)) {
  const m = Math.max(0, Math.min(s.end, (week + 1) * WEEK) - Math.max(s.start, week * WEEK));
  const regular = Math.min(m, Math.max(0, OVERTIME_AFTER - minutes));
  cents += Math.round((regular * w.rate + (m - regular) * w.rate * 1.5) / 60);
  minutes += m;
}
return cents;
